/** Logical query orders do not change the fixed persistent adjacency schema's physical write demand. */
class LmdbPersistentAdjacencyWriteEstimateTest {
	@Test
	void listCountAndMetadataEstimatesAgreeIndependentlyOfLogicalQueryOrders(@TempDir Path directory) throws Exception {
		var values = SimpleValueFactory.getInstance();
		var subject = values.createIRI("urn:write-estimate:subject");
		var predicate = values.createIRI("urn:write-estimate:predicate");
		var graph = values.createIRI("urn:write-estimate:graph");
		List<Statement> rows = List.of(values.createStatement(subject, predicate, values.createLiteral("one")),
				values.createStatement(subject, predicate, values.createLiteral("two"), graph),
				values.createStatement(values.createBNode("third"), predicate, subject));
		SailSource.WritePreflight metadata = new SailSource.WritePreflight(List.of(),
				List.of(new SailSource.NamespaceUpdate("estimate", "urn:write-estimate:")), Set.of("removed"),
				Set.of(graph), true, true);
		SailSource.WritePreflight complete = new SailSource.WritePreflight(rows, metadata.addedNamespaces(),
				metadata.removedNamespacePrefixes(), metadata.clearedContexts(), metadata.statementCleared(),
				metadata.namespaceCleared());
		List<Estimate> estimates = new ArrayList<>();
		for (String orders : List.of("spoc", "spoc,posc", "spoc,posc,ospc,cspo,cpos,cosp")) {
			try (TripleStore triples = new TripleStore(directory.resolve("orders-" + estimates.size()).toFile(),
					new LmdbStoreConfig(orders).setAutoGrow(false), null)) {
				estimates.add(
						new Estimate(orders, triples.estimateWriteBytes(rows), triples.estimateWriteBytes(rows.size()),
								triples.estimateWriteBytes(complete), triples.estimateWriteBytes(rows.size(), metadata),
								triples.estimateWriteBytes(metadata), triples.estimateWriteBytes(0, metadata),
								triples.estimateWriteBytes(List.of()), triples.estimateWriteBytes(0)));
			}
		}
		List<Executable> checks = new ArrayList<>();
		Estimate reference = estimates.getFirst();
		for (Estimate estimate : estimates) {
			checks.add(() -> assertTrue(estimate.count > 0, estimate.orders));
			checks.add(() -> assertEquals(estimate.count, estimate.list, "List/count demand: " + estimate.orders));
			checks.add(() -> assertEquals(estimate.countWithMetadata, estimate.listWithMetadata,
					"List/count metadata demand: " + estimate.orders));
			checks.add(() -> assertEquals(estimate.count + estimate.metadataOnly, estimate.countWithMetadata,
					"statement demand and metadata demand compose exactly once: " + estimate.orders));
			checks.add(() -> assertEquals(estimate.metadataOnly, estimate.countMetadataOnly, estimate.orders));
			checks.add(() -> assertEquals(0L, estimate.emptyList, estimate.orders));
			checks.add(() -> assertEquals(0L, estimate.emptyCount, estimate.orders));
			checks.add(() -> assertEquals(reference.list, estimate.list,
					"logical query order count cannot multiply persistent native writes: " + estimate.orders));
			checks.add(() -> assertEquals(reference.count, estimate.count, estimate.orders));
			checks.add(() -> assertEquals(reference.listWithMetadata, estimate.listWithMetadata, estimate.orders));
			checks.add(() -> assertEquals(reference.countWithMetadata, estimate.countWithMetadata, estimate.orders));
		}
		assertAll(checks);
	}

	@Test
	void onlyKnownSinglePlaneInputCollapsesAdjacentEqualQuads(@TempDir Path directory) throws Exception {
		var values = SimpleValueFactory.getInstance();
		var subject = values.createIRI("urn:estimate:subject");
		var predicate = values.createIRI("urn:estimate:predicate");
		var graph = values.createIRI("urn:estimate:graph");
		Statement a = values.createStatement(subject, predicate, values.createLiteral("a"));
		Statement equalA = values.createStatement(subject, predicate, values.createLiteral("a"));
		Statement b = values.createStatement(subject, predicate, values.createLiteral("b"));
		Statement graphA = values.createStatement(subject, predicate, values.createLiteral("a"), graph);
		Statement equalGraphA = values.createStatement(subject, predicate, values.createLiteral("a"), graph);
		List<Statement> rows = List.of(a, equalA, b, a, graphA, equalGraphA);
		int ordinal = 0;
		for (String orders : List.of("spoc", "spoc,posc,ospc,cspo,cpos,cosp")) {
			try (TripleStore triples = new TripleStore(directory.resolve("runs-" + ordinal++).toFile(),
					new LmdbStoreConfig(orders).setAutoGrow(false), null)) {
				assertEquals(triples.estimateWriteBytes(6), triples.estimateWriteBytes(rows),
						"generic merged preflight must retain possible cross-plane duplicate rows");
				assertEquals(triples.estimateWriteBytes(4), triples.estimateSinglePlaneWriteBytes(rows),
						"semantic equality collapses adjacent runs only, including context in the quad");
				assertEquals(triples.estimateWriteBytes(2), triples.estimateWriteBytes(List.of(a, equalA)));
				assertEquals(triples.estimateWriteBytes(1),
						triples.estimateSinglePlaneWriteBytes(List.of(a, equalA)));
				assertEquals(0L, triples.estimateSinglePlaneWriteBytes(List.of()));
			}
		}
	}

	private record Estimate(String orders, long list, long count, long listWithMetadata, long countWithMetadata,
			long metadataOnly, long countMetadataOnly, long emptyList, long emptyCount) {
	}
}
